<script setup lang="ts">
import {ref,watch,onBeforeUnmount,computed} from 'vue'
import FilesEditor from './FilesEditor.vue'
import AppModal from './AppModal.vue'
import AppIcon from './AppIcon.vue'
import {state,request,notify} from '../store'
const props=defineProps<{mode:'skills'|'mcp'}>()
interface Skill {id:string;name:string;description:string;enabled:boolean;builtin:boolean;revision:number;resources:string[]}
interface Server {id:string;name:string;transport:string;url:string;image:string;command:string;args:string[];network:string;timeout:number;enabled:boolean;status:string;error:string;tools:{name:string;agentName:string;description:string}[];credentialKeys:{headers:string[];env:string[]}}
const skills=ref<Skill[]>([]),servers=ref<Server[]>([]),loading=ref(false),busy=ref(false),error=ref(''),skillOpen=ref(false),serverOpen=ref(false),importOpen=ref(false),remove=ref<{kind:string;id:string;name:string}|null>(null),upload=ref<HTMLInputElement>()
const skill=ref({id:'',content:'',resources:'{}',enabled:true,builtin:false})
const defaultStdioImage=ref('')
function blankServer(){return {id:'',name:'',transport:'streamable-http',url:'',image:defaultStdioImage.value,command:'',args:'[]',network:'targets',timeout:30,enabled:true,headers:'',env:'',clear_credentials:false}}
const server=ref(blankServer()),importText=ref(''),credentialHint=ref('')
const probes=ref<Record<string,{id:string;status:string;summary:string}>>({})
const orderedSkills=computed(()=>[...skills.value].sort((a,b)=>Number(a.builtin)-Number(b.builtin)))
const customCount=computed(()=>skills.value.filter(s=>!s.builtin).length)
async function load(){const project=state.projectId;loading.value=true;try{const data=await request('/extensions');if(project===state.projectId){skills.value=data.skills;servers.value=data.servers;defaultStdioImage.value=data.defaults?.stdioImage||'';error.value=''}}catch(e){error.value=String(e)}finally{loading.value=false}}
watch(()=>state.projectId,()=>{skills.value=[];servers.value=[];probes.value={};skillOpen.value=false;serverOpen.value=false;importOpen.value=false;void load()},{immediate:true})
async function action(fn:()=>Promise<unknown>,message:string){if(busy.value)return;busy.value=true;try{await fn();notify(message);await load()}catch(e){notify(String(e))}finally{busy.value=false}}
function newSkill(){skill.value={id:'',content:'---\nname: my-testing-skill\ndescription: 说明什么时候使用这个 Skill。\n---\n\n# 测试方法\n\n写下测试流程、注意事项和需要时可读取的资源。\n',resources:'{}',enabled:true,builtin:false};skillOpen.value=true}
async function editSkill(item:Skill){try{if(item.builtin){const detail=await request('/tools/skills_read',{arguments:{name:item.name}});skill.value={id:item.id,content:detail.content,resources:'{}',enabled:true,builtin:true}}else{const detail=await request('/extensions/skills/'+item.id);const files={...detail.files};delete files['SKILL.md'];skill.value={id:item.id,content:detail.content,resources:JSON.stringify(files,null,2),enabled:item.enabled,builtin:false}}skillOpen.value=true}catch(e){notify(String(e))}}
function object(text:string,label:string){const value=JSON.parse(text||'{}');if(!value||Array.isArray(value)||typeof value!=='object'||Object.values(value).some(v=>typeof v!=='string'))throw Error(label+'需要“文件名或键: 文本值”的 JSON 对象');return value}
async function saveSkill(){await action(async()=>{await request('/extensions/skills',{id:skill.value.id,content:skill.value.content,resources:object(skill.value.resources,'辅助资源'),enabled:skill.value.enabled});skillOpen.value=false},'Skill 已保存，下一轮对话生效')}
async function importSkill(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;await action(async()=>{if(file.size>5_000_000)throw Error('Skill 上传文件最多 5 MB');const response=await fetch('/api/extensions/skills/import?filename='+encodeURIComponent(file.name),{method:'POST',headers:{'X-TestPilot-Project':state.projectId,'Content-Type':'application/octet-stream'},body:file});const data=await response.json();if(!response.ok)throw Error(data.message||data.detail||'导入失败')},'Skill 已导入并开启');if(upload.value)upload.value.value=''}
function newServer(){server.value=blankServer();credentialHint.value='';serverOpen.value=true}
function editServer(item:Server){server.value={...blankServer(),id:item.id,name:item.name,transport:item.transport,url:item.url,image:item.image,command:item.command,args:JSON.stringify(item.args),network:item.network,timeout:item.timeout,enabled:item.enabled};credentialHint.value=[...item.credentialKeys.headers.map(k=>'header: '+k),...item.credentialKeys.env.map(k=>'env: '+k)].join('、');serverOpen.value=true}
async function saveServer(){await action(async()=>{const data:Record<string,unknown>={...server.value,image:server.value.image.trim(),args:JSON.parse(server.value.args)};if(!Array.isArray(data.args))throw Error('命令参数需要 JSON 数组');if(!data.image)delete data.image;data.headers=server.value.headers.trim()?object(server.value.headers,'请求头'):undefined;data.env=server.value.env.trim()?object(server.value.env,'环境变量'):undefined;await request('/extensions/mcp',data);serverOpen.value=false},'MCP 已保存，可检查连接；下一轮对话生效')}
async function importServers(){await action(async()=>{await request('/extensions/mcp/import',{configuration:JSON.parse(importText.value)});importOpen.value=false;importText.value=''},'MCP 配置已导入')}
async function toggle(kind:string,item:Skill|Server){await action(()=>request('/extensions/'+kind+'/'+item.id+'/enabled',{enabled:!item.enabled}),'启用状态已更新')}
async function probe(item:Server){try{const result=await request('/extensions/mcp/'+item.id+'/probe',{});probes.value[item.id]=result;notify('正在检查连接和工具列表')}catch(e){notify(String(e))}}
let polling=false
const timer=setInterval(async()=>{if(polling)return;const project=state.projectId;const pending=Object.entries(probes.value).filter(([,v])=>['queued','running'].includes(v.status));if(!pending.length)return;polling=true;try{for(const [key,value] of pending){const result=await request('/extensions/probes/'+value.id);if(project!==state.projectId)break;probes.value[key]=result;if(!['queued','running'].includes(result.status))await load()}}catch(e){notify(String(e));probes.value={}}finally{polling=false}},1500)
onBeforeUnmount(()=>clearInterval(timer))
async function confirmRemove(){if(!remove.value)return;const item=remove.value;await action(async()=>{await request('/extensions/'+item.kind+'/'+item.id+'/delete',{});remove.value=null},'扩展已删除')}
function connectionLabel(item:Server){if(!item.enabled)return '已关闭';if(['queued','running'].includes(probes.value[item.id]?.status||''))return '检查中';return item.status==='connected'?'连接成功':item.status==='error'?'连接失败':'待检查'}
function resourceFiles(){try{return JSON.parse(skill.value.resources||'{}')}catch{return {}}}
</script>
<template>
<section class="panel settings-card extension-manager">
  <div class="settings-section-title"><div><h2>{{mode==='skills'?'Skill 方法库':'为 TestPilot 接入外部工具'}}</h2><p>{{mode==='skills'?'Agent 先看名称与描述，再按任务读取说明和资源。':'将其他服务提供的工具引入 TestPilot Agent 的多轮对话。'}}</p></div><span class="plain-tag">{{mode==='skills'?customCount+' 个自定义':servers.length+' 个连接'}} · 当前项目</span></div>
  <div class="extension-toolbar" v-if="mode==='skills'"><button class="button primary" @click="newSkill"><AppIcon name="plus" :size="16"/>新建 Skill</button><button class="button secondary" :disabled="busy" @click="upload?.click()">导入 SKILL.md / ZIP</button><input ref="upload" type="file" class="sr-only" tabindex="-1" aria-label="导入 Skill 文件" accept=".md,.zip" @change="importSkill"/><span class="muted">开启与修改在下一轮对话生效</span></div>
  <div class="extension-toolbar" v-else><button class="button primary" @click="newServer"><AppIcon name="plus" :size="16"/>添加 MCP</button><button class="button secondary" @click="importOpen=true">导入 MCP JSON</button><button class="button secondary" :disabled="loading" @click="load">刷新</button></div>
  <p v-if="error" class="extension-error">{{error}}</p>
  <div v-if="mode==='skills'" class="skill-list"><article v-for="item in orderedSkills" :key="item.id" class="extension-row"><span class="skill-icon"><AppIcon name="book" :size="20"/></span><div class="extension-info"><h3>{{item.name}} <span class="plain-tag">{{item.builtin?'内置':'v'+item.revision}}</span></h3><p>{{item.description}}</p><small>{{item.resources.length}} 个资源</small></div><div class="extension-actions"><button class="text-button" @click="editSkill(item)">{{item.builtin?'查看':'编辑'}}</button><button v-if="!item.builtin" class="button secondary compact" :disabled="busy" :aria-label="(item.enabled?'关闭':'开启')+' Skill '+item.name" @click="toggle('skills',item)">{{item.enabled?'已开启':'已关闭'}}</button><button v-if="!item.builtin" class="text-button danger" @click="remove={kind:'skills',id:item.id,name:item.name}">删除</button></div></article></div>
  <div v-else class="mcp-list"><p v-if="!servers.length&&!loading" class="empty-state">还没有外部 MCP。添加地址或导入配置后，先检查连接。</p><article v-for="item in servers" :key="item.id" class="mcp-card"><div class="extension-row"><span class="skill-icon"><AppIcon name="chain" :size="20"/></span><div class="extension-info"><h3>{{item.name}} <span class="plain-tag" :class="{'extension-error-tag':item.status==='error'}">{{connectionLabel(item)}}</span></h3><p>{{item.transport==='stdio'?'stdio · '+item.image+' · '+item.command:item.transport+' · '+item.url}}</p></div><div class="extension-actions"><button class="text-button" :disabled="['queued','running'].includes(probes[item.id]?.status||'')" @click="probe(item)">检查连接</button><button class="text-button" @click="editServer(item)">编辑</button><button class="button secondary compact" :disabled="busy" :aria-label="(item.enabled?'关闭':'开启')+' MCP '+item.name" @click="toggle('mcp',item)">{{item.enabled?'已开启':'已关闭'}}</button><button class="text-button danger" @click="remove={kind:'mcp',id:item.id,name:item.name}">删除</button></div></div><p v-if="item.error" class="extension-error">{{item.error}}</p><p v-if="probes[item.id]" class="form-hint">{{probes[item.id].summary}}</p><details v-if="item.tools.length" class="mcp-tool-list"><summary>{{item.tools.length}} 个工具 · 查看名称和用途</summary><div v-for="tool in item.tools" :key="tool.name"><strong>{{tool.name}}</strong><p>{{tool.description}}</p><code>{{tool.agentName}}</code></div></details></article></div>
  <details class="skill-principle"><summary>工作方式与支持范围</summary><div class="principle-content"><AppIcon name="sparkles" :size="18"/><div><strong>{{mode==='skills'?'说明书按需读取，脚本自主执行':'工具由 Agent 选择，结果继续参与下一轮决策'}}</strong><p>{{mode==='skills'?'Skill 不绑定固定入口。可以附带 scripts/*.py 等文本资源，Agent 读取后决定是否复制到工作区执行，或调用测试工具。':'支持 Streamable HTTP、SSE 与隔离容器中的 stdio。每个项目最多接入 60 个 MCP 工具。调用参数与结果可在 Agent 对话中展开查看；连接失败会明确提示。'}}</p></div></div></details>
  <details v-if="mode==='skills'" class="advanced-section"><summary>Agent 的核心工具</summary><div class="section-label">核心工具</div><div class="tool-chips"><code v-for="tool in ['project_context','cases_save_revision','runs_start','runs_get','browser_explore','workspace_exec','skills_list','skills_read']" :key="tool">{{tool}}</code></div></details>
</section>
<AppModal :open="skillOpen" :title="skill.builtin?'查看内置 Skill':skill.id?'编辑 Skill':'新建 Skill'" @close="skillOpen=false"><form class="extension-form" @submit.prevent="saveSkill"><label class="field-label">SKILL.md<textarea v-model="skill.content" class="extension-code" rows="14" :readonly="skill.builtin" required spellcheck="false"/></label><template v-if="!skill.builtin"><section><h3>辅助资源</h3><FilesEditor title="资源文件" hint="上传说明文档或脚本，供 Agent 按需读取。文件名可填写 scripts/check.py 这样的相对路径。" accept=".md,.txt,.csv,.json,.yaml,.yml,.py,.js,.ts,.sh" :model-value="resourceFiles()" @update:model-value="skill.resources=JSON.stringify($event,null,2)"/><p class="form-hint">相对路径对应文本资源，也可导入包含 SKILL.md 和脚本的 ZIP。</p></section><label class="step-enable"><input v-model="skill.enabled" type="checkbox"/>在当前项目开启</label><div class="modal-actions"><button type="button" class="button secondary" @click="skillOpen=false">取消</button><button class="button primary" :disabled="busy">保存 Skill</button></div></template></form></AppModal>
<AppModal :open="serverOpen" :title="server.id?'编辑 MCP 连接':'添加 MCP 连接'" @close="serverOpen=false"><form class="extension-form" @submit.prevent="saveServer"><div class="config-grid"><label class="field-label">连接名称<input v-model="server.name" required maxlength="80" placeholder="例如项目文档工具"/></label><label class="field-label">传输方式<select v-model="server.transport" class="select"><option value="streamable-http">Streamable HTTP</option><option value="sse">SSE（旧版）</option><option value="stdio">stdio（隔离容器）</option></select></label></div><label v-if="server.transport!=='stdio'" class="field-label">MCP 地址<input v-model="server.url" type="url" required placeholder="http://mcp-server:8000/mcp"/><small>填写 Worker 可访问的地址。容器内的 127.0.0.1 指 Worker 自己。</small></label><template v-else><label class="field-label">容器镜像<input v-model="server.image" :placeholder="defaultStdioImage||'当前部署的执行镜像'"/><small>留空使用当前部署的执行镜像；自定义镜像需已安装于 Docker。npx / Node 工具请使用含 Node 的镜像。</small></label><div class="config-grid"><label class="field-label">入口命令<input v-model="server.command" required placeholder="python"/></label><label class="field-label">命令参数（JSON 数组）<input v-model="server.args" required placeholder='["-m","my_mcp_server"]'/></label></div><label class="field-label">容器网络<select v-model="server.network" class="select"><option value="targets">测试目标网络</option><option value="internet">联网（Docker bridge）</option><option value="none">无网络</option></select></label><p class="form-hint">命令在独立容器执行，不挂载主机项目和 Docker socket，不继承模型或数据库密钥。请使用镜像内的路径。</p></template><details class="extension-credentials"><summary>请求头与环境变量</summary><p class="form-hint">已有键：{{credentialHint||'无'}}。留空保留原值；填写 {} 清空该组。保存后不回显明文。</p><label class="field-label">请求头（JSON）<textarea v-model="server.headers" class="extension-code" rows="3" placeholder='{"Authorization":"Bearer YOUR_TOKEN"}' spellcheck="false"/></label><label class="field-label">环境变量（JSON）<textarea v-model="server.env" class="extension-code" rows="3" placeholder='{"SERVICE_TOKEN":"YOUR_TOKEN"}' spellcheck="false"/></label><label class="step-enable"><input v-model="server.clear_credentials" type="checkbox"/>清除原有凭据，再保存本次填写的值</label></details><div class="config-grid"><label class="field-label">工具调用超时（秒）<input v-model.number="server.timeout" type="number" min="5" max="120" required/></label><label class="step-enable"><input v-model="server.enabled" type="checkbox"/>引入当前项目 Agent</label></div><div class="modal-actions"><button type="button" class="button secondary" @click="serverOpen=false">取消</button><button class="button primary" :disabled="busy">保存 MCP</button></div></form></AppModal>
<AppModal :open="importOpen" title="导入 MCP 配置" @close="importOpen=false"><form class="extension-form" @submit.prevent="importServers"><label class="field-label">mcpServers JSON<textarea v-model="importText" rows="12" class="extension-code" required spellcheck="false" placeholder='{"mcpServers":{"docs":{"url":"http://server:8000/mcp","headers":{}}}}'/></label><p class="form-hint">支持 url / command / args / env / headers。stdio 配置可加 image 和 network；命令在容器里执行，主机 cwd 与本机文件路径需要调整。</p><div class="modal-actions"><button type="button" class="button secondary" @click="importOpen=false">取消</button><button class="button primary" :disabled="busy">导入配置</button></div></form></AppModal>
<AppModal :open="!!remove" title="删除扩展" @close="remove=null"><div class="extension-form"><p>删除 {{remove?.name}}？后续对话将无法读取或调用它，历史对话保留。</p><div class="modal-actions"><button class="button secondary" @click="remove=null">取消</button><button class="button primary" :disabled="busy" @click="confirmRemove">确认删除</button></div></div></AppModal>
</template>
